# Check additional oligodendrocyte and neural markers
neural_genes = ['MBP', 'MOG', 'CNP', 'SOX10', 'OLIG2', 'GFAP', 'S100B', 'VIM', 'ALDH1L1', 'DCX', 'TUBB3']

import numpy as np
from scipy.sparse import issparse

print("Neural/glia marker expression per cluster:\n")
print(f"{'Gene':<12} {'Cluster 0':>10} {'Cluster 3':>10} {'Cluster 12':>10} {'Cluster 18':>10}")
print("-" * 60)

for gene in neural_genes:
    if gene in adata.var_names:
        idx = list(adata.var_names).index(gene)
        expr_by_cluster = {}
        for cluster in ['0', '3', '12', '18']:
            cells = adata.obs[adata.obs['leiden'] == cluster].index
            cluster_X = adata[cells].X
            if issparse(cluster_X):
                cluster_mean = np.array(cluster_X[:, idx].mean(axis=0)).flatten()[0]
            else:
                cluster_mean = cluster_X[:, idx].mean(axis=0)
            expr_by_cluster[cluster] = f"{cluster_mean:.2f}"

        print(f"{gene:<12} {expr_by_cluster['0']:>10} {expr_by_cluster['3']:>10} {expr_by_cluster['12']:>10} {expr_by_cluster['18']:>10}")
    else:
        print(f"{gene:<12} {'N/A':>10} {'N/A':>10} {'N/A':>10} {'N/A':>10}")
